from pathlib import Path
import shutil
r=Path('HiroseSFGNote').resolve();p=r/'中文版本/第一章 SFG快速入门/1.1 红外-可见光和频振动光谱（SFG）入门.md';o=r/'翻译管理/校订记录/1.1';s=p.read_text(encoding='utf-8');a=s.index('\u200b\t上述公式表示的是');b=s.index('**（三阶极化－1：双波长光引起的四波混合）**',a);assert not (o/'B007-修订前.md').exists();shutil.copy2(p,o/'B007-修订前.md')
t=r'''上述各式给出的是相应的极化系数：由 $\omega_1$ 光电场在 $j$ 轴上的分量 $E_j$ 和 $\omega_2$ 光电场在 $k$ 轴上的分量 $E_k$，产生沿 $i$ 轴的极化分量 $P_i$。因此，求总极化时，对 $i=x,y,z$ 中的每一个分量，都要考虑 $(j,k)=(x,x),(x,y),\ldots$ 共 9 种组合；只有一束入射光时，则为 6 种组合。另外，$\rho_g^{(0)}$ 表示没有光微扰时处于状态 $g$ 的分子比例，即在状态 $g$ 中找到分子的概率。

在式（10）、式（11）右边的第一组项中，方括号前的因子对应 $\omega_2$ 光引起的、从状态 $g$ 到状态 $n$ 的吸收跃迁概率振幅。方括号内的部分，则与经电子激发态 $n'$、由 $(\omega_1+\omega_2)$ 光引起的 $g$ 到 $n$ 跃迁所对应的拉曼散射张量具有相同形式；乘以使量纲一致的系数后，两者相符。由此得到和频过程与差频过程的振动共振选择规则：**只有同时具有线性吸收活性和拉曼散射活性的振动模式，才能产生 SFG、DFG 的振动共振。**

第二组项对应 $\omega_2$ 光引起的、从状态 $g$ 到能量更低的状态 $n'$ 的吸收跃迁概率振幅，并与经状态 $n$、在相同初末态之间发生跃迁的振动拉曼散射，即反斯托克斯拉曼散射的张量具有相同形式；同样，乘以使量纲一致的系数后，两者相符。第三、第四组项分别由第一、第二组项交换 $\omega_1$ 光与 $\omega_2$ 光得到，涉及的是 $\omega_1$ 光的线性吸收，而非 $\omega_2$ 光的线性吸收。

现令 $\omega_2$ 光为红外光，$\omega_1$ 光为可见光。式（10）、式（11）右边的第一、第二组项，分别给出与吸收型（向上）和受激发射型（向下）振动跃迁的共振。另外，生成光与电子跃迁共振时，方括号内的部分会增大，因此电子共振会使和频光与差频光整体增强。另一方面，第三、第四组项给出可见光引起的共振；在红外–可见光 SFG 光谱中，这些项对所谓的背景光有贡献。当生成光，即 $(\omega_1+\omega_2)$ 光或 $(\omega_1-\omega_2)$ 光，与电子跃迁共振时，这种背景光信号也会增大。

可见光频率 $\omega_1$ 与生成光频率 $\omega_1+\omega_2$ 之差为红外光频率 $\omega_2$。不过，电子跃迁具有振动结构，而且凝聚相中的光谱通常较宽，因此一般认为，出现电子共振时，振动共振增强的同时也会产生背景光。还应注意，固体中也可能存在核四极跃迁引起的和频过程与差频过程，因此不能仅凭有背景光，就立即断定存在电子共振。

'''
head=s[:a].replace('差频式（11）及其整流/DFG说明（B003–B006），其后解释段仍为待校订旧译。','式（11）后的跨页解释段（B003–B007），三阶响应式起仍为待校订旧译。').replace('第 4 页至式（11）后的说明。','第 4–5 页至三阶响应段之前。');p.write_text(head+t+s[b:],encoding='utf-8')
assert p.read_text(encoding='utf-8').split('**（三阶极化－1：双波长光引起的四波混合）**',1)[1]==s.split('**（三阶极化－1：双波长光引起的四波混合）**',1)[1]
print('B007 explanatory paragraphs revised; no numbered formula added; third-order section unchanged.')
